/**
 * RichTextContent.Inlines: a paragraph’s or a heading’s drawn inlines, each as the element or member of its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { useContext, type JSX } from 'solid-js'

import {
  Each,
  claimSlot,
  classes,
  mergeParts,
  ownerContext,
  richTextPositionAttrs,
  scope,
  type RichTextDrawnInline,
  type RichTextEntity,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import Code from './Code'
import Link from '../controls/Link'
import type { RichTextContentOwner } from './RichTextContent'

export interface RichTextContentInlinesProps {
  inlines: RichTextDrawnInline[]
}

/** RichTextContent.Inlines: a paragraph’s or a heading’s drawn inlines, each as the element or member of its kind. */
export default function RichTextContentInlines(given: RichTextContentInlinesProps): JSX.Element {
  const props = claimSlot(given)
  const owner =
    useContext(ownerContext<RichTextContentOwner>('RichTextContent')) ??
    ({} as RichTextContentOwner)
  return scope(() => {
    return (
      <Each of={props.inlines} by={(_node, index) => index} renew>
        {(node) => (
          <>
            {node.kind === 'text' ? (
              node.text
            ) : node.kind === 'strong' ? (
              <strong>
                <RichTextContentInlines inlines={node.children} />
              </strong>
            ) : node.kind === 'em' ? (
              <em>
                <RichTextContentInlines inlines={node.children} />
              </em>
            ) : node.kind === 's' ? (
              <s>
                <RichTextContentInlines inlines={node.children} />
              </s>
            ) : node.kind === 'mark' ? (
              <mark
                class={classes(styles.annotation, owner.pressable ? styles.pressable : undefined)}
                data-annotation-id={node.id}
                data-active={node.active ? '' : undefined}
                role={node.stop ? 'button' : undefined}
                tabindex={node.stop ? '0' : undefined}
                aria-current={node.stop && node.active ? 'true' : undefined}
              >
                <RichTextContentInlines inlines={node.children} />
              </mark>
            ) : node.kind === 'code' ? (
              <Code>{node.text}</Code>
            ) : node.kind === 'ownCode' ? (
              <code class={styles.code}>
                <RichTextContentInlines inlines={node.children} />
              </code>
            ) : node.kind === 'link' && owner.routes ? (
              <Link
                href={node.href}
                external={node.external}
                onNavigate={($event) => (owner.navigate as (href: string) => void)($event)}
              >
                {node.text}
              </Link>
            ) : node.kind === 'link' ? (
              <Link href={node.href} external={node.external}>
                {node.text}
              </Link>
            ) : node.kind === 'break' ? (
              <br {...mergeParts(richTextPositionAttrs(node.at, true))} />
            ) : node.kind === 'entity' && node.app ? (
              (owner.entityNode as (entity: RichTextEntity) => never)(node.entity)
            ) : node.kind === 'entity' ? (
              <span
                class={styles.entity}
                data-entity-kind={node.entity.kind}
                data-entity-id={node.entity.id}
              >
                {node.entity.label}
              </span>
            ) : node.kind === 'piece' ? (
              <span {...mergeParts(richTextPositionAttrs(node.at, node.atom, false))}>
                <RichTextContentInlines inlines={node.children} />
              </span>
            ) : null}
          </>
        )}
      </Each>
    )
  })
}
